function closeToast(id){const el=document.getElementById(id);if(el){el.style.opacity='0';el.style.transform='translateX(20px)';setTimeout(()=>el.remove(),400);}}
setTimeout(()=>{document.querySelectorAll('.toast-item').forEach(t=>closeToast(t.id));},5000);;$(document).ready(function(){console.log('صفحه لود شد');function initPersianDatepicker(){console.log('شروع فعال‌سازی datepicker');var $dateInput=$('#birthdate-picker');if($dateInput.length===0){console.error('فیلد birthdate-picker پیدا نشد!');return;}
console.log('فیلد تاریخ پیدا شد:',$dateInput.attr('id'));if($dateInput.data('pd')){console.log('datepicker قبلی نابود شد');$dateInput.data('pd').destroy();$dateInput.removeData('pd');}
$dateInput.val('');$dateInput.persianDatepicker({format:'YYYY/MM/DD',autoClose:true,initialValue:false,initialValueType:null,observer:false,calendar:{persian:{locale:'fa',showHint:true,leapYearMode:'algorithmic'}},toolbox:{enabled:true,calendarSwitch:{enabled:false},todayButton:{enabled:false},submitButton:{enabled:true,text:'انتخاب'}},timePicker:{enabled:false,showSeconds:false,showMeridian:false},onSelect:function(pd){console.log('تاریخ انتخاب شد:',pd.format('YYYY/MM/DD'));$dateInput.val(pd.format('YYYY/MM/DD'));},onInit:function(){console.log('Datepicker مقداردهی اولیه شد');this.selectedTime=null;}});console.log('Datepicker فعال شد');}
function setupTabSwitching(){$(".tab a").on("click",function(e){e.preventDefault();$(".tab").removeClass("active");$(this).parent().addClass("active");$(".tab-content > div").hide().removeClass("active");const target=$(this).attr("href");$(target).fadeIn(200).addClass("active");if(target==='#signup'){setTimeout(function(){console.log('تب ثبت نام باز شد - فعال‌سازی datepicker');initPersianDatepicker();},100);}
$(target).find("input:first").focus();});}
function setupLabels(){$(".form").find("input, select").on("focus blur change keyup",function(){const label=$(this).prev("label");if($(this).val()){label.addClass("active");}else{label.removeClass("active");}});}
if($('#signup').is(':visible')){console.log('صفحه با تب ثبت نام لود شد');setTimeout(function(){initPersianDatepicker();},300);}
setupTabSwitching();setupLabels();setTimeout(function(){if($('#birthdate-picker').length&&!$('#birthdate-picker').val()){$('#birthdate-picker').val('');}},1000);});;$(".form").find("input, select").on("focus blur change keyup",function(){const label=$(this).prev("label");if($(this).val()){label.addClass("active");}else{label.removeClass("active");}});$(".tab a").on("click",function(e){e.preventDefault();$(".tab").removeClass("active");$(this).parent().addClass("active");$(".tab-content > div").hide().removeClass("active");const target=$(this).attr("href");$(target).fadeIn(200).addClass("active");$(target).find("input:first").focus();});;